#!/usr/bin/env node
// Usage: node tools/generate-sticks.mjs [export-html-path]
// Extracts the STICKS array from an exported yao-qian-yuan-xing artifact HTML
// and regenerates supabase/seed.sql + sites/yuelao/src/ritual/sticks.ts from it.
// The export is the single source of truth; never hand-edit the generated files.
// Fails loudly unless the export contains exactly 100 unique sticks.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const exportPath =
  process.argv[2] ??
  path.join(process.env.HOME ?? '', 'workspace/your_files/yao-qian-yuan-xing/yao-qian-yuan-xing.html');

function extractSticks(html) {
  const idx = html.search(/STICKS\s*=\s*\[/);
  if (idx < 0) throw new Error('STICKS array not found in export');
  const start = html.indexOf('[', idx);
  let depth = 0;
  let i = start;
  let inStr = false;
  let strCh = '';
  let esc = false;
  for (; i < html.length; i++) {
    const c = html[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === strCh) inStr = false;
      continue;
    }
    if (c === '"' || c === "'" || c === '`') {
      inStr = true;
      strCh = c;
      continue;
    }
    if (c === '[') depth++;
    else if (c === ']') {
      depth--;
      if (depth === 0) break;
    }
  }
  // The input is our own artifact export (a JS array literal with unquoted keys, so
  // JSON.parse cannot read it). This generator runs locally at build time only,
  // never in the browser and never on untrusted input.
  // biome-ignore lint/security/noGlobalEval: build-time generator script, trusted input only.
  return eval(html.slice(start, i + 1));
}

function validate(sticks) {
  if (!Array.isArray(sticks) || sticks.length !== 100) {
    throw new Error(
      `expected exactly 100 sticks, got ${Array.isArray(sticks) ? sticks.length : typeof sticks}`,
    );
  }
  const nos = new Set();
  for (const [i, s] of sticks.entries()) {
    if (typeof s.no !== 'string' || nos.has(s.no)) throw new Error(`stick ${i}: bad or duplicate no`);
    nos.add(s.no);
    if (!s.grade || !Number.isInteger(s.level) || s.level < 0 || s.level > 5) {
      throw new Error(`stick ${s.no}: bad grade/level`);
    }
    if (!s.knot || !s.knotName) throw new Error(`stick ${s.no}: missing knot`);
    const lines = String(s.poem ?? '').split('\n');
    if (lines.length !== 4 || lines.some((l) => l.length !== 7)) {
      throw new Error(`stick ${s.no}: poem must be 4 lines of 7 chars`);
    }
    for (const key of ['him', 'single', 'reunion']) {
      if (typeof s.verdict?.[key] !== 'string' || !s.verdict[key]) {
        throw new Error(`stick ${s.no}: missing verdict.${key}`);
      }
    }
  }
}

const sqlLit = (v) => `'${String(v).replace(/'/g, "''")}'`;

function seedSql(sticks) {
  const rows = sticks
    .map(
      (s, i) =>
        `(${i + 1}, ${sqlLit(s.no)}, ${sqlLit(s.grade)}, ${s.level}, ${sqlLit(s.knot)}, ${sqlLit(s.knotName)}, ${sqlLit(s.poem)}, ${sqlLit(s.verdict.him)}, ${sqlLit(s.verdict.single)}, ${sqlLit(s.verdict.reunion)})`,
    )
    .join(',\n');
  return `-- GENERATED by tools/generate-sticks.mjs from the yao-qian-yuan-xing artifact export.
-- Do not hand-edit: re-export the artifact and re-run the generator.
-- Source data: 100 prototype sticks (newly written for the prototype; the formal
-- 籤詩底本 is still undecided — see AGENTS.md. Replace this seed when the 底本 is set).
-- stick_locales (Simplified) is intentionally empty here: Simplified copy is translated
-- in P1; the app falls back to the Traditional text until then.
-- deep_readings (paid deep readings) is intentionally empty: content debt, see BUILD_PLAN §9 #4.
insert into sticks (id, no, grade, level, knot, knot_name, poem, verdict_him, verdict_single, verdict_reunion)
values
${rows}
on conflict (id) do update set
  no = excluded.no, grade = excluded.grade, level = excluded.level,
  knot = excluded.knot, knot_name = excluded.knot_name, poem = excluded.poem,
  verdict_him = excluded.verdict_him, verdict_single = excluded.verdict_single,
  verdict_reunion = excluded.verdict_reunion;
`;
}

function sticksTs(sticks) {
  const data = sticks.map((s, i) => ({
    id: i + 1,
    no: s.no,
    grade: s.grade,
    level: s.level,
    knot: s.knot,
    knotName: s.knotName,
    poem: s.poem,
    verdict: s.verdict,
  }));
  return `// GENERATED by tools/generate-sticks.mjs from the yao-qian-yuan-xing artifact export.
// Do not hand-edit: re-export the artifact and re-run the generator.
// Same source as supabase/seed.sql; the build keeps the two in sync by regeneration.
// Prototype text — the formal 籤詩底本 is still undecided (see AGENTS.md).
export interface Stick {
  id: number;
  no: string;
  grade: string;
  level: number;
  knot: string;
  knotName: string;
  poem: string;
  verdict: { him: string; single: string; reunion: string };
}

export const STICKS: Stick[] = ${JSON.stringify(data, null, 2)};

export const STICK_COUNT = STICKS.length;

export function stickById(id: number): Stick | undefined {
  return STICKS.find((s) => s.id === id);
}
`;
}

const html = fs.readFileSync(exportPath, 'utf8');
const sticks = extractSticks(html);
validate(sticks);
fs.writeFileSync(path.join(root, 'supabase/seed.sql'), seedSql(sticks));
fs.writeFileSync(path.join(root, 'sites/yuelao/src/ritual/sticks.ts'), sticksTs(sticks));
const grades = {};
for (const s of sticks) grades[s.grade] = (grades[s.grade] ?? 0) + 1;
console.log(`sticks: ${sticks.length}, grades: ${JSON.stringify(grades)}`);
console.log('wrote supabase/seed.sql + sites/yuelao/src/ritual/sticks.ts');
